def _resolve_orient_width(
    self,
    df: DataFrame,
    orient: str,
    mark: Mark,
    subplots: list[dict],
    scales: dict[str, Scale],
    share_state: str | None,
) -> DataFrame:
    """Calculate width values for orientation axis."""
    if orient not in df:
        return df

    width = pd.Series(index=df.index, dtype=float)
    for view in subplots:
        view_idx = self._get_subplot_data(df, orient, view, share_state).index
        view_df = df.loc[view_idx]
        if "width" in mark._mappable_props:
            view_width = mark._resolve(view_df, "width", None)
        elif "width" in df:
            view_width = view_df["width"]
        else:
            view_width = 0.8
        spacing = scales[orient]._spacing(view_df.loc[view_idx, orient])
        width.loc[view_idx] = view_width * spacing
    df["width"] = width
    return df

def _resolve_baseline(self, df: DataFrame, mark: Mark) -> DataFrame:
    """Resolve baseline values for the mark."""
    if "baseline" in mark._mappable_props:
        baseline = mark._resolve(df, "baseline", None)
    else:
        baseline = 0 if "baseline" not in df else df["baseline"]
    df["baseline"] = baseline
    return df

def _apply_move_transformations(
    self,
    df: DataFrame,
    move: Move | list[Move] | None,
    orient: str,
    scales: dict[str, Scale],
    grouping_properties: list[str],
    default_grouping_vars: list[str],
    get_order: Callable,
) -> DataFrame:
    """Apply move transformations to the data."""
    if move is None:
        return df

    moves = move if isinstance(move, list) else [move]
    for move_step in moves:
        move_by = getattr(move_step, "by", None)
        if move_by is None:
            move_by = grouping_properties
        move_groupers = [*move_by, *default_grouping_vars]
        if move_step.group_by_orient:
            move_groupers.insert(0, orient)
        order = {var: get_order(var) for var in move_groupers}
        groupby = GroupBy(order)
        df = move_step(df, groupby, orient, scales)
    return df

def _invert_coordinates(
    self, df: DataFrame, subplots: list[dict]
) -> DataFrame:
    """Transform scaled coordinates back to data space."""
    coord_cols = [c for c in df if re.match(r"^[xy]\D*$", str(c))]
    unscaled_df = (
        df
        .drop(coord_cols, axis=1)
        .reindex(df.columns, axis=1)
        .copy(deep=False)
    )

    for view in subplots:
        filtered_view_df = filter_subplot_rows(df, view)
        axes_values = filtered_view_df[coord_cols]
        for var, values in axes_values.items():
            axis = getattr(view["ax"], f"{str(var)[0]}axis")
            transform = axis.get_transform().inverted().transform
            inverted = transform(values)
            unscaled_df.loc[values.index, str(var)] = inverted

    return unscaled_df

def _prepare_grouping_data(
    self, df: DataFrame, mark: Mark, default_grouping_vars: list[str]
) -> tuple[list[str], list[list]]:
    """Prepare grouping variables and keys for mark rendering."""
    grouping_vars = mark._grouping_props + default_grouping_vars
    active_grouping_vars = [
        v for v in grouping_vars if v in df and v not in ["col", "row"]
    ]
    grouping_keys = []
    for gv in active_grouping_vars:
        key_order = getattr(self._scales[gv], "order", None)
        if key_order is None:
            key_order = categorical_order(df[gv])
        grouping_keys.append(key_order)
    return active_grouping_vars, grouping_keys

